import uuid
import operator
from typing import Dict, Any, List, TypedDict, Optional, Annotated


# Generated by GitHub Copilot
class AgentState(TypedDict):
    """Shared state passed between LangGraph nodes during an agent flow execution."""
    article_id: uuid.UUID
    author_id: uuid.UUID
    # Proyecto bajo el que corre la ejecución (SPEC-013 / T8.5 / AC6). Va en el
    # estado y no en una variable de módulo porque varios pipelines de proyectos
    # distintos pueden estar en vuelo a la vez en el mismo proceso.
    project_id: Optional[uuid.UUID]
    title: str
    keywords: List[str]
    research_data: str
    sources: List[Dict[str, Any]]
    draft_text: str
    feedback: Annotated[List[str], operator.add]
    approval_score: float
    # `ok` | `not_verified` (el Revisor no produjo una revisión interpretable; SPEC-032/AC15)
    review_status: str
    formatted_text: str
    scientific_format: str
    # Fuentes que el Formateador dejó fuera por incompletas, con los campos que faltan (SPEC-032/AC2)
    reference_issues: List[Dict[str, Any]]
    published_url: str
    # La compuerta de publicación bloqueó el texto final y qué criterios (SPEC-032/AC14)
    gate_failed: bool
    gate_blockers: List[Dict[str, Any]]
    metadata: Dict[str, Any]
    flow_sequence: List[str]
    current_step_index: int
    loop_count: int
    # Per-agent model overrides: {"redactor": {"model": "mistral:7b"}, ...}
    agent_settings: Dict[str, Dict[str, Any]]
    # Optional context/focus description provided by the user when launching the pipeline
    context_description: str
    article_outline: str
    # Parámetros de esta ejecución concreta (SPEC-030 / T18.3 / AC3, AC7). Van en
    # el estado porque los lee quien ejecuta, y acaban en `agent_run_steps.params`
    # para que dos pasadas del mismo artículo con parámetros distintos se
    # distingan a posteriori.
    #: Notas libres, acotadas y tratadas como dato (ver `platform/run_config.py`).
    swarm_notes: str
    #: Documento de referencia acotado a esta ejecución (T18.1 / AC1).
    reference_doc_id: Optional[str]
    #: Cómo se aprende el formato: 'rag' o 'finetune' (AC6).
    format_mode: str
    # Human-in-the-loop coherence gate (revisor):
    coherent: bool                  # whether the revisor judged the draft coherent
    user_decision: Optional[str]    # "add_source" | "continue" | None (per revisor pass)
    source_retries: int             # how many times the user added a source and retried
